/* v3 günlər, toplu ixrac və arxiv funksiyaları */
function semesterIsArchived(semesterId){return (v.data?.archive_batches||[]).some(b=>b.semester_id===semesterId);}
function writeTouchesArchive(table,row){
 if(!row)return false;
 if(table==='semesters')return semesterIsArchived(row.id);
 if(table==='offerings')return semesterIsArchived(row.semester_id);
 if(table==='sessions')return semesterIsArchived(by('offerings',row.offering_id)?.semester_id);
 if(table==='attendance')return semesterIsArchived(by('offerings',by('sessions',row.session_id)?.offering_id)?.semester_id);
 if(table==='assessment_events')return semesterIsArchived(by('offerings',row.offering_id)?.semester_id);
 if(table==='assessment_marks')return semesterIsArchived(by('offerings',by('assessment_events',row.event_id)?.offering_id)?.semester_id);
 return false;
}
function seedV3(data){
 data.archive_batches??=[];data.archive_entries??=[];
 for(const s of data.semesters){
  if(!Object.hasOwn(s,'ends_on'))s.ends_on=(s.number===1?'2027-01-31':'2027-06-30');
 }
 // Yalnız qondarma tarixli məlumatlar: köhnə semestrin arxiv prosesini sınaqdan keçirmək üçün.
 if(!data.academic_years.some(x=>x.id==='yold')){
  data.academic_years.push({id:'yold',label:'2025/2026 (demo)',is_current:false});
  data.semesters.push({id:'sold',academic_year_id:'yold',number:2,is_current:false,ends_on:'2026-06-30'});
  data.offerings.push({id:'oold',semester_id:'sold',group_id:'g1',subject_id:'s1',lecture_teacher_id:'lecture',seminar_teacher_id:'seminar',lecture_hours:30,seminar_hours:30,credits:5,absence_limit_pct:25});
  const ids=data.students.slice(0,24).map(st=>st.id);
  for(const st of ids)data.enrollments.push({id:'old-'+st,student_id:st,group_id:'g1',academic_year_id:'yold'});
  const ss=[{id:'ol1',offering_id:'oold',kind:'lecture',lesson_date:'2026-04-13',topic:'Pedaqoji fəaliyyətə giriş',lesson_hours:2,notes:'',is_consultation:false,confirmed_at:'2026-04-13T10:00:00Z',confirmed_by:'lecture'},
  {id:'os1',offering_id:'oold',kind:'seminar',lesson_date:'2026-04-14',topic:'Təlim metodlarının müzakirəsi',lesson_hours:2,notes:'',is_consultation:false,confirmed_at:'2026-04-14T10:00:00Z',confirmed_by:'seminar'}];
  data.sessions.push(...ss);
  for(const st of ids){data.attendance.push({session_id:'ol1',student_id:st,value:st==='st1'?'qb':'ie',note:''},{session_id:'os1',student_id:st,value:st==='st2'?'qb':'8',note:''});}
  for(let i=1;i<=3;i++)data.assessment_events.push({id:'oc'+i,offering_id:'oold',kind:'seminar',type:'colloquium',ordinal:i,title:i+'-ci kollokvium',held_on:'2026-05-'+String(i*5+1).padStart(2,'0')});
 }
 return data;
}
